import React, { useState, useEffect } from 'react';
import axios from 'axios';
import TeacherQuiz from './TeacherQuiz';
import TeacherContent from './TeacherContent';

export default function TeacherDashboard({ userName, userUsername, subject, qualifications, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [isEditing, setIsEditing] = useState(false);

  const fullSubject = subject || 'Not Set';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 10';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const [profileData, setProfileData] = useState({ 
      name: userName || '', username: userUsername || '', qualifications: qualifications || '',
      email: email || '', phone: phone || '', address: address || '' 
  });

  const fetchData = () => {
    axios.get('http://localhost:8081/api/learning-materials').then(res => setMaterials(res.data));
    axios.get('http://localhost:8081/api/timetable').then(res => {
        setTimetable(res.data.filter(c => c.teacher === userName));
    });
  };

  useEffect(() => {
    fetchData();
    setProfileData({ name: userName, username: userUsername, qualifications: qualifications || 'B.Sc. Teacher', email, phone, address });
  }, [userName, userUsername, qualifications, email, phone, address]);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <h1 style={{ margin: 0 }}>Welcome back, {profileData.name}! 👋</h1>
              <p style={{ margin: '5px 0 0 0', opacity: 0.9 }}>Your Aura Pen Teacher Portal is fully operational.</p>
            </div>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" textColor="#3b82f6" />
              <DashboardCard title="Assigned Grades" count={teachingGrade} icon="🏫" textColor="#7c3aed" />
              <DashboardCard title="Total Uploads" count={materials.length} icon="📂" textColor="#eab308" />
            </div>

            <h2 style={{ color: '#1e293b', marginBottom: '15px' }}>🏫 My Live Classes</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                {timetable.map(c => (
                  <div key={c.id} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderTop: `5px solid #3b82f6` }}>
                    <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold' }}>{c.grade}</div>
                    <h3 style={{ margin: '5px 0' }}>{c.subject}</h3>
                    <p style={{ color: '#64748b', fontSize: '13px' }}>🕒 {c.day} ({c.time_slot})</p>
                  </div>
                ))}
            </div>
          </div>
        );

      case 'upload':
        // වෙනම ෆයිල් එකක් වන TeacherContent එකට Props Pass කිරීම
        return <TeacherContent userName={userName} teachingSubject={teachingSubject} materials={materials} fetchData={fetchData} />;

      case 'quiz':
        // වෙනම ෆයිල් එකක් වන TeacherQuiz එකට Props Pass කිරීම
        return <TeacherQuiz userName={userName} teachingSubject={teachingSubject} teachingGrade={teachingGrade} />;

      case 'profile':
        return (
          <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
            <div style={{ flex: 1, backgroundColor: 'white', padding: '30px', borderRadius: '15px' }}>
              <h3>👤 Profile Details</h3>
              <input type="text" value={profileData.name} disabled style={inputStyle} />
              <input type="text" value={teachingSubject} disabled style={inputStyle} />
              <input type="text" value={profileData.email} disabled style={inputStyle} />
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 15px', display: 'flex', flexDirection: 'column', gap: '5px' }}>
        <h2 style={{ textAlign: 'center', marginBottom: '30px' }}>Aura Pen Saku</h2>
        <button onClick={() => setActiveTab('dashboard')} style={sideBtn(activeTab === 'dashboard')}>🏠 Dashboard</button>
        <button onClick={() => setActiveTab('upload')} style={sideBtn(activeTab === 'upload')}>📤 Content Manager</button>
        <button onClick={() => setActiveTab('quiz')} style={sideBtn(activeTab === 'quiz')}>📝 Quiz Manager</button>
        <button onClick={() => setActiveTab('profile')} style={sideBtn(activeTab === 'profile')}>👤 My Profile</button>
        <button onClick={handleLogout} style={{ marginTop: 'auto', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>🚪 Logout</button>
      </div>
      <div style={{ flex: 1, padding: '40px', overflowY: 'auto' }}>{renderContent()}</div>
    </div>
  );
}

const sideBtn = (active) => ({ width: '100%', padding: '14px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '8px', textAlign: 'left', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' });
const DashboardCard = ({ title, count, icon, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${textColor}`, boxShadow: '0 4px 15px rgba(0,0,0,0.02)' }}>
    <div><p style={{ margin: 0, color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2>{count}</h2></div>
    <div style={{ fontSize: '28px' }}>{icon}</div>
  </div>
);
const inputStyle = { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', marginBottom: '15px', backgroundColor: '#f8fafc' };
